1	//! Integration tests for the per-file ± line counts `changed_files` now returns, against REAL
2	//! throwaway jj repos. Skips if `jj` isn't on PATH — and says so out loud; see
3	//! `tests/common/mod.rs`.
4	//!
5	//! These counts used to be added app-side from a SECOND read — one `jj diff -r @ --stat` process,
6	//! run after the native file list. Three separate defects came out of that split, and the tests below
7	//! pin each one:
8	//!
9	//! 1. `-r @` on a **merge** diffs the auto-merged parents, while the file list is a tree diff against
10	//!    the FIRST parent — so the totals described a different set of files than the rows beside them.
11	//!    A single-parent fixture cannot expose this (the two bases coincide), so
12	//!    `merge_working_copy_counts_against_the_first_parent` needs a real merge — and it asserts jj's own
13	//!    `-r @` number to show the old path really was wrong, not just differently derived.
14	//! 2. Two reads of a moving working copy can disagree; counts now come from the same snapshot as the
15	//!    list, which is what `counts_match_jj_diff_stat_for_a_linear_working_copy` measures against jj.
16	//! 3. A conflicted file's materialized markers count as changed lines. That is *kept* — it's what jj
17	//!    and git both report for the same state — and pinned here so the app's "counts include conflict
18	//!    markers" wording stays true.
19	//!
20	//! `working_status` MUTATES (working-copy lock → snapshot → rewrite `@`), so every fixture is a
21	//! throwaway dir under the temp dir, never a real repo.
22	
23	use std::path::Path;
24	use std::path::PathBuf;
25	use std::process::Command;
26	
27	use wr_vcs_core::model::ChangeKind;
28	use wr_vcs_core::model::ChangedFile;
29	
30	mod common;
31	
32	/// Run `jj` in `dir` with `config` as its ONLY config file. Passed per-`Command` rather than through
33	/// `std::env::set_var`, which would race the other tests in this parallel process.
34	fn jj(args: &[&str], dir: &Path, config: &Path) -> std::process::Output {
35	    Command::new("jj")
36	        .args(args)
37	        .current_dir(dir)
38	        .env("JJ_CONFIG", config)
39	        .output()
40	        .unwrap_or_else(|e| panic!("run jj {args:?}: {e}"))
41	}
42	
43	/// A fresh throwaway repo: unique dir, isolated jj config (supplying an author so snapshot operations
44	/// can commit), `jj git init` run.
45	fn init_repo(tag: &str) -> (PathBuf, PathBuf) {
46	    let dir = std::env::temp_dir().join(format!("wr-stats-{}-{}", std::process::id(), tag));
47	    let _ = std::fs::remove_dir_all(&dir);
48	    std::fs::create_dir_all(&dir).unwrap();
49	    let config = dir.join("jjconfig.toml");
50	    std::fs::write(
51	        &config,
52	        b"[user]\nname = \"Test\"\nemail = \"test@example.com\"\n",
53	    )
54	    .unwrap();
55	    let init = jj(&["git", "init"], &dir, &config);
56	    assert!(
57	        init.status.success(),
58	        "jj git init: {}",
59	        String::from_utf8_lossy(&init.stderr)
60	    );
61	    (dir, config)
62	}
