85	/// jj's OWN totals for a diff, parsed from `jj diff --stat`'s summary line — the exact string the app
86	/// used to parse app-side. Used here as the cross-check that our native fold agrees with jj where it
87	/// should, and disagrees where jj is answering a different question (`-r @` on a merge).
88	fn jj_stat_totals(args: &[&str], dir: &Path, cfg: &Path) -> (u32, u32) {
89	    let mut full = vec!["diff"];
90	    full.extend_from_slice(args);
91	    full.extend_from_slice(&["--ignore-working-copy", "--stat", "--color", "never"]);
92	    let out = jj(&full, dir, cfg);
93	    let text = String::from_utf8_lossy(&out.stdout);
94	    let summary = text.lines().last().unwrap_or_default();
95	    let count = |suffix: &str| -> u32 {
96	        summary
97	            .split(", ")
98	            .find(|part| part.contains(suffix))
99	            .and_then(|part| part.split_whitespace().next())
100	            .and_then(|n| n.parse().ok())
101	            .unwrap_or(0)
102	    };
103	    (count("insertion"), count("deletion"))
104	}
