106	fn file<'a>(files: &'a [ChangedFile], path: &str) -> &'a ChangedFile {
107	    files
108	        .iter()
109	        .find(|f| f.path == path)
110	        .unwrap_or_else(|| panic!("{path} missing from {files:?}"))
111	}
