113	/// Sum the rows the way the app's Changes header does. Files with `None` counts (binary, oversized,
114	/// non-file) contribute nothing, matching how git and jj both leave binaries out of a diffstat.
115	fn totals(files: &[ChangedFile]) -> (u32, u32) {
116	    files.iter().fold((0, 0), |(ins, del), f| {
117	        (
118	            ins + f.insertions.unwrap_or(0),
119	            del + f.deletions.unwrap_or(0),
120	        )
121	    })
122	}
