131	/// `jj_backend::MAX_COUNTED_BYTES`, mirrored because a private const can't be imported from an
132	/// integration test. Not a duplicate to keep in sync by hand: the two size fixtures below are built
133	/// *from* this value and assert they clear it, so if the backend's cap ever moves upward the fixture
134	/// stops being oversized and its test fails — which is exactly the right failure, since the claim
135	/// being pinned is "content over the cap is not counted".
136	const MAX_COUNTED_BYTES: usize = 4 * 1024 * 1024;
137	
138	/// At least `bytes` of plain, NUL-free text, every line distinct and tagged with `marker`.
139	///
140	/// Distinct lines matter twice over: nothing here may look binary (`looks_binary` would otherwise
141	/// answer before the size check, and the size tests would pass without a size check existing at
142	/// all), and nothing may coincidentally collapse in a diff.
143	///
144	/// Lines are ~512 bytes, which is both realistic and cheap. Realistic because the files that
145	/// actually hit this cap are generated and minified ones — long lines are their shape. Cheap because
146	/// the line count, not the byte count, is what `diff_by_line` and jj's conflict merge scale on:
147	/// at ~80 bytes per line the conflict fixture below spent an extra second tokenizing 50k lines to
148	/// prove nothing the 8k-line version doesn't.
149	fn text_of_size(bytes: usize, marker: &str) -> Vec<u8> {
150	    let filler = "-".repeat(480);
151	    let mut out = Vec::with_capacity(bytes + 128);
152	    let mut n: u64 = 0;
153	    while out.len() < bytes {
154	        out.extend_from_slice(format!("{marker} line {n:012} {filler}\n").as_bytes());
155	        n += 1;
156	    }
157	    assert!(!out.contains(&0), "the fixture must be TEXT, not binary");
158	    out
159	}
