497	
498	    // A quarter over the cap: clear of it by megabytes, so this can never turn into an off-by-one
499	    // test, and clear enough that a modest future raise of the cap fails loudly rather than subtly.
500	    let huge = text_of_size(MAX_COUNTED_BYTES + MAX_COUNTED_BYTES / 4, "grown");
501	    assert!(
502	        huge.len() > MAX_COUNTED_BYTES,
503	        "fixture ({} bytes) must exceed the cap ({MAX_COUNTED_BYTES} bytes) — if the backend raised \
504	         it, raise this fixture too",
505	        huge.len()
506	    );
