516	    );
517	    assert_eq!(
518	        (big.insertions, big.deletions),
519	        (None, None),
520	        "over the cap is not counted — `None`, never a partial count from the truncated read; got \
521	         {big:?}"
522	    );
523	    // And it poisons neither its neighbour nor the header total.
