623	/// Symlink entries report `None`: there is no file content to diff, only a target string.
624	///
625	/// `side_content` groups `Symlink` with `Tree`/`GitSubmodule`/`OtherConflict`/`AccessDenied` in a
626	/// single `None` arm, and nothing pinned that. `Symlink` is the plausible one to lose — its `target`
627	/// is right there in the value, and "count the target as one line" reads like a fix — so moving it
628	/// into a counting arm would have shipped green.
629	///
630	/// Both shapes are covered because they reach `side_content` differently: a RETARGETED link is
631	/// `Symlink → Symlink`, while a NEW link is `Absent → Symlink`, and only the second proves the
632	/// `Absent` arm's "empty content" answer doesn't rescue an uncountable other side (`line_stats`
633	/// short-circuits on the FIRST `None`, so a regression could easily be visible on one and not the
634	/// other).
635	///
636	/// Unix-only: a symlink is the subject, and `std::os::unix::fs::symlink` is how you make one on the
637	/// two platforms this crate is built for (macOS locally, Linux on CI).
638	#[cfg(unix)]
639	#[test]
640	fn symlink_changes_report_no_counts() {
641	    if common::skip_without(&["jj"], "symlink stats test") {
642	        return;
643	    }
644	    let (dir, cfg) = init_repo("symlink");
645	    std::fs::write(dir.join("a.txt"), b"a\n").unwrap();
646	    std::fs::write(dir.join("b.txt"), b"b\n").unwrap();
647	    std::fs::write(dir.join("c.txt"), b"one\n").unwrap();
648	    std::os::unix::fs::symlink("a.txt", dir.join("link")).unwrap();
649	    jj(&["commit", "-m", "base"], &dir, &cfg);
650	
651	    // Retarget the tracked link, add a brand-new one, and make one ordinary edit beside them — the
652	    // edit is what keeps "nothing was counted" from being trivially true of the whole read.
653	    std::fs::remove_file(dir.join("link")).unwrap();
654	    std::os::unix::fs::symlink("b.txt", dir.join("link")).unwrap();
655	    std::os::unix::fs::symlink("a.txt", dir.join("fresh")).unwrap();
656	    std::fs::write(dir.join("c.txt"), b"one\ntwo\n").unwrap();
657	
658	    let files = working_files(&dir);
659	    let link = file(&files, "link");
660	    assert_eq!(
661	        link.kind,
662	        ChangeKind::Modified,
663	        "a retargeted symlink is still a listed change; got {link:?}"
664	    );
665	    assert_eq!(
666	        (link.insertions, link.deletions),
667	        (None, None),
668	        "a symlink has a target, not lines; got {link:?}"
669	    );
670	    let fresh = file(&files, "fresh");
671	    assert_eq!(
672	        fresh.kind,
673	        ChangeKind::Added,
674	        "a new symlink is an Added row; got {fresh:?}"
675	    );
676	    assert_eq!(
677	        (fresh.insertions, fresh.deletions),
678	        (None, None),
679	        "an absent before-side must not rescue an uncountable after-side; got {fresh:?}"
680	    );
681	    assert_eq!(file(&files, "c.txt").insertions, Some(1));
682	    assert_eq!(totals(&files), (1, 0));
683	
684	    let _ = std::fs::remove_dir_all(&dir);
685	}
